const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',pipeline:'<path d="M4 6h16M4 12h10M4 18h6"/><circle cx="18" cy="17" r="3"/>',projects:'<path d="M3 7.5A1.5 1.5 0 0 1 4.5 6H10l2 2h7.5A1.5 1.5 0 0 1 21 9.5v9a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 18.5z"/>',accounts:'<circle cx="9" cy="8" r="3"/><path d="M3 20c.5-3.3 2.5-5 6-5s5.5 1.7 6 5M16 5.3a3 3 0 0 1 0 5.8M17 15c2.5.4 3.8 2 4 5"/>',duplicates:'<circle cx="8" cy="8" r="5"/><circle cx="16" cy="16" r="5"/><path d="m11.5 11.5 1 1"/>',reports:'<path d="M4 19V5M4 19h17M8 15l4-5 3 2 5-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.6.9l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.6-.9l-1.7.7-1.4-2.4 1.4-1.1a7 7 0 0 1 0-1.9l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.6-.9l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.6.9l1.7-.7 1.4 2.4-1.4 1.1a7 7 0 0 1 0 1.8Z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',money:'<path d="M12 2v20M17 5.5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"'};
const svg=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.home}</svg>`;
const uid=()=>crypto.randomUUID();
const today=new Date();const iso=(d)=>{const x=new Date(d);return new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const money=(n,compact=false)=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0,notation:compact?'compact':'standard'}).format(Number(n||0));
const month=(date)=>new Intl.DateTimeFormat('en',{month:'short'}).format(new Date(`${date}-01T12:00:00`));
const dateOffset=(n)=>{const d=new Date();d.setDate(d.getDate()+n);return iso(d)};
const stages=['Start','Meeting planned','Meeting has happened','Quote in process','Quote sent'];
const seed={accounts:[{id:'a1',name:'Northstar Foods',industry:'Food & beverage',size:'51–200',kind:'Client',contact:'Mira Kovac',email:'mira@northstar.example'},{id:'a2',name:'Lumen Works',industry:'Industrial design',size:'11–50',kind:'Client',contact:'Adam Varga',email:'adam@lumen.example'},{id:'a3',name:'Greenfield Labs',industry:'Technology',size:'11–50',kind:'Lead',contact:'Elena Novak',email:'elena@greenfield.example'},{id:'a4',name:'Studio Vela',industry:'Creative services',size:'1–10',kind:'Vendor',contact:'Tomas Urban',email:'hello@velastudio.example'}],deals:[{id:'d1',accountId:'a3',name:'Website & brand foundation',stage:'Quote sent',value:18000,probability:52,owner:'Alex',nextActivity:dateOffset(2),createdAt:dateOffset(-18)},{id:'d2',accountId:'a2',name:'LinkedIn growth programme',stage:'Quote in process',value:9600,probability:50,owner:'Maya',nextActivity:dateOffset(1),createdAt:dateOffset(-13)},{id:'d3',accountId:'a1',name:'Brand strategy workshop',stage:'Meeting has happened',value:6800,probability:38,owner:'Alex',nextActivity:dateOffset(4),createdAt:dateOffset(-8)},{id:'d4',accountId:'a3',name:'Digital growth retainer',stage:'Meeting planned',value:24000,probability:37,owner:'Maya',nextActivity:dateOffset(5),createdAt:dateOffset(-5)},{id:'d5',accountId:'a2',name:'Customer journey review',stage:'Start',value:4200,probability:35,owner:'Alex',nextActivity:dateOffset(7),createdAt:dateOffset(-2)},{id:'d6',accountId:'a1',name:'Campaign optimisation',stage:'Quote sent',value:7500,probability:52,owner:'Maya',nextActivity:dateOffset(3),createdAt:dateOffset(-22)}],projects:[{id:'p1',accountId:'a1',name:'Northstar brand platform',group:'Strategia',status:'In delivery',contractValue:24000,startDate:'2026-09-01',endDate:'2027-02-28',owner:'Maya',marginPlan:0.42,services:[{name:'Brand strategy',value:9000},{name:'Visual identity',value:10000},{name:'Supervision',value:5000}]},{id:'p2',accountId:'a2',name:'Lumen digital presence',group:'Transformacia',status:'In delivery',contractValue:18000,startDate:'2026-07-01',endDate:'2026-12-31',owner:'Alex',marginPlan:0.35,services:[{name:'New website',value:14000},{name:'Content design',value:4000}]},{id:'p3',accountId:'a1',name:'Northstar LinkedIn',group:'Taktika',status:'Scheduled',contractValue:12000,startDate:'2026-11-01',endDate:'2027-04-30',owner:'Maya',marginPlan:0.45,services:[{name:'LinkedIn management',value:12000}]}],plans:[{projectId:'p1',value:24000,startDate:'2026-09-01',endDate:'2027-02-28',method:'proportional'},{projectId:'p2',value:18000,startDate:'2026-07-01',endDate:'2026-12-31',method:'proportional'},{projectId:'p3',value:12000,startDate:'2026-11-01',endDate:'2027-04-30',method:'proportional'}],costs:[{id:'c1',projectId:'p1',vendor:'Vela Studio',description:'Identity production',planned:3800,actual:1900,status:'In progress',date:'2026-10-14'},{id:'c2',projectId:'p2',vendor:'Brightside Dev',description:'Website development',planned:5200,actual:3900,status:'In progress',date:'2026-10-11'},{id:'c3',projectId:'p2',vendor:'Lingo House',description:'Copy adaptation',planned:1100,actual:0,status:'Planned',date:'2026-11-01'}],invoices:[{id:'i1',projectId:'p1',number:'SF-2026-118',amount:4000,issued:'2026-09-03',status:'Paid'},{id:'i2',projectId:'p2',number:'SF-2026-104',amount:6000,issued:'2026-08-01',status:'Paid'},{id:'i3',projectId:'p2',number:'SF-2026-131',amount:3000,issued:'2026-10-01',status:'Sent'}]};
let state=loadState(),view='Overview',searchTerm='',selectedProject=null,backend={url:'',key:'',email:'',password:'',token:'',connected:false};
state.agreements??=[];try{backend={...backend,...JSON.parse(localStorage.getItem('bc_backend')||'{}')}}catch{}
const app=document.querySelector('#app');
const supabaseSession=createSupabaseSession({getBackend:()=>backend,setBackend:next=>{backend=next;localStorage.setItem('bc_backend',JSON.stringify({...next,password:''}));}});
const migration=createMigration({request:supa,connected:()=>backend.connected&&!backend.sessionExpired,render:()=>render(),escape:esc,pageHead,modal,toast});
const reconciliation=createReconciliation({request:supa,connected:()=>backend.connected&&!backend.sessionExpired,render:()=>render(),escape:esc,pageHead,reloadWorkspace,modal,openSource:row=>{view='Source records';render();migration.focus(row.source_container_id,row.raw_record.name);}});
const leadWorkflow=createLeadWorkflow({escape:esc,money,account,openReview:reviewLead});
const duplicates=createDuplicates({request:supa,connected:()=>backend.connected&&!backend.sessionExpired,accounts:()=>state.accounts||[],contacts:()=>state.contacts||[],reload:reloadWorkspace,render:()=>render(),pageHead,modal,toast,escape:esc});
function loadState(){try{return JSON.parse(localStorage.getItem('bc_state'))||structuredClone(seed)}catch{return structuredClone(seed)}}
function save(){localStorage.setItem('bc_state',JSON.stringify(state));if(backend.connected)syncState().catch(e=>toast(`Local change saved; Supabase sync failed: ${e.message}`))}
function account(id){return state.accounts.find(x=>x.id===id)||{name:'Unknown account'}}
function project(id){return state.projects.find(x=>x.id===id)}
function plannedFor(p,ym){const projectPlans=state.plans.filter(x=>x.projectId===p.id);if(!projectPlans.length)return 0;const manual=projectPlans.filter(x=>x.month);if(manual.length)return manual.filter(x=>x.month.slice(0,7)===ym).reduce((s,x)=>s+Number(x.value),0);const plan=projectPlans[0],from=new Date(`${plan.startDate.slice(0,7)}-01T12:00:00`),to=new Date(`${plan.endDate.slice(0,7)}-01T01:00:00`),m=new Date(`${ym}-01T12:00:00`);if(m<from||m>to)return 0;const months=(to.getFullYear()-from.getFullYear())*12+to.getMonth()-from.getMonth()+1;return plan.method==='proportional'?Number(plan.value)/months:0}
function scheduleRows(projectId,total,startDate,endDate,pattern,manualRaw=''){const from=new Date(`${startDate.slice(0,7)}-01T12:00:00`),to=new Date(`${endDate.slice(0,7)}-01T12:00:00`),count=(to.getFullYear()-from.getFullYear())*12+to.getMonth()-from.getMonth()+1;if(count<1)throw new Error('End date must be on or after the start date.');if(pattern==='proportional')return[{projectId,value:+total,startDate,endDate,method:'proportional'}];const amounts=manualRaw.split(',').map(x=>Number(x.trim()));if(amounts.length!==count||amounts.some(x=>!Number.isFinite(x)||x<0)||Math.abs(amounts.reduce((a,x)=>a+x,0)-Number(total))>.01)throw new Error(`Enter ${count} monthly amounts that add up to ${money(total)}.`);return amounts.map((value,i)=>{const d=new Date(from);d.setMonth(d.getMonth()+i);return{projectId,value,method:'manual',month:d.toISOString().slice(0,7)}})}
function actualFor(ym){return state.invoices.filter(i=>i.issued?.slice(0,7)===ym).reduce((s,x)=>s+Number(x.amount),0)}
function monthKey(d){return d.toISOString().slice(0,7)}
function getMonthSeries(){return Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+i-2);const k=monthKey(d);return{key:k,label:new Intl.DateTimeFormat('en',{month:'short'}).format(d),plan:state.projects.reduce((s,p)=>s+plannedFor(p,k),0),actual:actualFor(k)}})}
const expectedPipeline=()=>state.deals.filter(d=>!['Won','Lost'].includes(d.stage)).reduce((s,d)=>s+Number(d.value)*Number(d.probability)/100,0);
const contracted=()=>state.projects.reduce((s,p)=>s+Number(p.contractValue),0);
const signedThisYear=()=>state.projects.filter(p=>p.startDate?.slice(0,4)==String(new Date().getFullYear())).reduce((s,p)=>s+Number(p.contractValue),0);
function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),2600)}
function navigate(v){view=v;selectedProject=null;render();if(v==='Source records')migration.load();if(v==='Reconciliation')reconciliation.load();if(v==='Duplicate review')duplicates.load()}
function navItem(v,icon,count=''){return`<a href="#" class="nav-item ${view===v?'active':''}" data-nav="${v}">${svg(icon)}<span>${v}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`}
function shell(content){return`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">B</div><div><strong>BizBase</strong><small>Studio operations</small></div></div><div class="workspace"><i class="workspace-dot"></i><div class="workspace-label">BizBase workspace<small>${backend.connected?(backend.sessionExpired?'Reconnect required':'Supabase connected'):'Demo workspace'}</small></div></div><div class="nav-group"><div class="nav-title">Workspace</div>${navItem('Overview','home')}${navItem('Pipeline','pipeline',String(state.deals.filter(d=>!['Won','Lost'].includes(d.stage)).length+state.leads.filter(l=>!l.promotedOpportunityId).length))}${navItem('Projects','projects',String(state.projects.length))}${navItem('Accounts','accounts')}${navItem('Duplicate review','duplicates')}</div><div class="nav-group"><div class="nav-title">Insights</div>${navItem('Reports','reports')}${navItem('Reconciliation','reports')}${navItem('Source records','projects')}</div><div class="side-bottom"><div class="nav-group">${navItem('Settings','settings')}</div><div class="profile"><div class="avatar">${backend.connected?esc((backend.email||'?').slice(0,2).toUpperCase()):'DM'}</div><div><strong>${backend.connected?esc(backend.email):'Demo user'}</strong><small>Workspace admin</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="top-icon menu-toggle" data-menu>${svg('menu')}</button><span>Workspace</span> &nbsp;/&nbsp; <b>${view}</b></div><div class="top-actions"><span class="conn-status ${backend.connected?'connected':''}"><i></i>${backend.connected?(backend.sessionExpired?'Reconnect required':'Supabase connected'):'Demo data'}</span><button class="top-icon" title="Notifications">${svg('bell')}</button><div class="top-avatar">${backend.connected?esc((backend.email||'?').slice(0,2).toUpperCase()):'DM'}</div></div></header><section class="page">${content}</section></main></div>`}
function pageHead(title,subtitle,action=''){return`<div class="page-head"><div><div class="eyebrow">${title==='Overview'?new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()):'Business console'}</div><h1>${title}</h1><div class="subhead">${subtitle}</div></div><div class="head-actions">${action}</div></div>`}
function stat(label,value,foot,icon,trend=''){return`<div class="stat"><div class="stat-top"><span>${label}</span><div class="stat-icon">${svg(icon)}</div></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<span class="trend">${trend}</span> · `:''}${foot}</div></div>`}
function chart(){const rows=getMonthSeries(),max=Math.max(1,...rows.flatMap(x=>[x.plan,x.actual]));return`<div class="bar-chart">${rows.map(r=>`<div class="month-col"><div class="bar plan" style="height:${Math.max(3,r.plan/max*145)}px" title="Revenue plan ${money(r.plan)}"></div><div class="bar actual" style="height:${Math.max(3,r.actual/max*145)}px" title="Invoiced ${money(r.actual)}"></div><span class="month-label">${r.label}</span></div>`).join('')}</div><div class="legend"><span><i></i>Revenue plan</span><span><i class="act"></i>Invoiced</span><span><i class="proj"></i>Projected</span></div>`}
function overview(){const yr=new Date().getFullYear(),series=getMonthSeries(),monthNow=monthKey(new Date()),curr=series.find(x=>x.key===monthNow)||{plan:0,actual:0},costs=state.costs.reduce((s,c)=>s+Number(c.planned),0),actualCosts=state.costs.reduce((s,c)=>s+Number(c.actual),0);const action=`<button class="btn" data-action="export">Export data</button><button class="btn lime" data-modal="lead">${svg('plus')} New lead</button>`;return pageHead('Overview','A clear view of what is selling, what is being delivered, and what comes next.',action)+(!backend.connected?`<div class="notice"><i class="dot"></i><span><b>Demo workspace</b> · This screen uses fictional sample records saved in this browser. Connect Supabase in Settings to work with shared records.</span><button class="link" data-nav="Settings">Connect</button></div>`:'')+`<div class="stats">${stat('Contract value',money(contracted(),true),backend.connected?'Imported values need review':'Across active & scheduled projects','money',`${state.projects.length} projects`)}${stat('Weighted pipeline',money(expectedPipeline(),true),'Open opportunities, weighted by stage','pipeline',`${state.deals.filter(d=>!['Won','Lost'].includes(d.stage)).length} open deals`)}${stat('Revenue plan · this month',money(curr.plan,true),backend.connected&&!state.invoices.length?'Invoice reconciliation pending':`${money(curr.actual)} invoiced so far`,'calendar')}${stat('Planned external costs',money(costs,true),state.costs.some(c=>c.actualPending)?'Actual cost verification pending':`${money(actualCosts)} recorded actuals`,'projects')}</div><div class="grid-2"><div class="card"><div class="card-head"><div><div class="card-title">Revenue plan</div><div class="card-sub">Monthly delivery plan and invoiced revenue · EUR</div></div><button class="link" data-nav="Reports">View report ${svg('arrow')}</button></div><div class="card-body">${chart()}</div></div><div class="card"><div class="card-head"><div><div class="card-title">Pipeline by stage</div><div class="card-sub">Open deal value and current probability</div></div><button class="link" data-nav="Pipeline">Open pipeline ${svg('arrow')}</button></div><div class="card-body"><div class="pipeline-list">${stages.map(s=>{let sum=state.deals.filter(d=>d.stage===s).reduce((a,d)=>a+Number(d.value),0),pc=state.deals.filter(d=>d.stage===s).reduce((a,d)=>a+Number(d.value)*Number(d.probability)/100,0);return`<div class="pipeline-row"><div class="stage">${s}</div><div class="pipeline-track"><i style="width:${sum?Math.max(6,Math.round(sum/Math.max(1,...stages.map(t=>state.deals.filter(d=>d.stage===t).reduce((a,d)=>a+Number(d.value),0)))*100)):0}%"></i></div><div class="pipeline-value">${money(pc,true)}</div></div>`}).join('')}</div><div class="pipeline-note">Weighted forecast: ${money(expectedPipeline())} · Expected close dates are set per opportunity.</div></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><div><div class="card-title">Projects to watch</div><div class="card-sub">Active and upcoming delivery with financial context</div></div><button class="link" data-nav="Projects">All projects ${svg('arrow')}</button></div><div class="table-wrap">${projectTable(state.projects.slice(0,4))}</div></div>`}
function projectTable(list){const groups=['Strategia','Transformacia','Taktika'],statuses=['Draft','Scheduled','In delivery','Paused','Completed','Cancelled'];return`<table class="table editable-table"><thead><tr><th>Project</th><th>Group</th><th>Status</th><th>Contract value · EUR</th><th>Plan through end</th><th>Owner</th></tr></thead><tbody>${list.length?list.map(p=>`<tr data-project="${esc(p.id)}" class="clickable"><td><div class="table-name"><div class="mini-mark">${esc((p.group||'?').slice(0,1))}</div><div><input class="cell-editor cell-name" aria-label="Project name" data-edit-project="${esc(p.id)}" data-field="name" value="${esc(p.name)}"><span class="secondary">${esc(account(p.accountId).name)}${p.dataQuality&&p.dataQuality!=='Verified'?' · Needs review':''}</span></div></div></td><td><select class="cell-editor" aria-label="Project group" data-edit-project="${esc(p.id)}" data-field="group">${groups.map(g=>`<option ${g===p.group?'selected':''}>${g}</option>`).join('')}</select></td><td><select class="cell-editor" aria-label="Project status" data-edit-project="${esc(p.id)}" data-field="status">${[...new Set([...statuses,p.status])].map(s=>`<option ${s===p.status?'selected':''}>${esc(s)}</option>`).join('')}</select></td><td><input class="cell-editor cell-money" aria-label="Contract revenue in EUR" type="number" min="0" step="0.01" data-edit-project="${esc(p.id)}" data-field="contractValue" value="${Number(p.contractValue)||0}"></td><td><input class="cell-editor cell-date" aria-label="Plan through end" type="date" data-edit-project="${esc(p.id)}" data-field="endDate" value="${esc(p.endDate||'')}" required></td><td><input class="cell-editor cell-owner" aria-label="Project owner" data-edit-project="${esc(p.id)}" data-field="owner" value="${esc(p.owner||'')}" placeholder="Add owner"></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No projects yet.</td></tr>`}</tbody></table>`}
function pipeline(){const action=`<button class="btn" data-modal="lead">${svg('plus')} Add raw lead</button><button class="btn primary" data-modal="deal">${svg('plus')} New opportunity</button>`;const cards=state.deals.filter(d=>!['Won','Lost'].includes(d.stage)).filter(d=>!searchTerm||`${d.name} ${account(d.accountId).name}`.toLowerCase().includes(searchTerm.toLowerCase()));return pageHead('Pipeline','Review new enquiries, qualify promising leads, and progress active opportunities.',action)+`<div class="toolbar"><div class="search">${svg('search')}<input id="search" placeholder="Search leads, deals or accounts" value="${esc(searchTerm)}"></div><div class="filters"><span class="pill">${state.leads.filter(l=>!l.promotedOpportunityId).length} unqualified leads</span><span class="pill">${cards.length} opportunities</span><span class="pill">${money(cards.reduce((s,d)=>s+Number(d.value),0))} opportunity value</span><span class="pill">${money(expectedPipeline())} weighted forecast</span></div></div><div class="board">${leadWorkflow.column(state.leads,searchTerm)}${stages.map(stage=>{const deals=cards.filter(x=>x.stage===stage);return`<div class="board-col"><div class="board-col-head"><strong>${stage}</strong><span>${deals.length} · ${money(deals.reduce((s,d)=>s+Number(d.value),0),true)}</span></div>${deals.length?deals.map(d=>`<div class="deal-card"><h3>${esc(d.name)}</h3><p>${esc(account(d.accountId).name)}</p><div class="deal-meta"><strong>${money(d.value)}</strong><span class="deal-owner">${esc(d.owner||'Unassigned')}</span></div><div class="split" style="margin-top:9px"><span class="status dot ${d.nextActivity<iso(new Date())?'orange':'blue'}">${d.nextActivity?`Next · ${new Intl.DateTimeFormat('en',{day:'numeric',month:'short'}).format(new Date(d.nextActivity+'T12:00:00'))}`:'No activity'}</span><select class="stage-change" data-deal="${d.id}" aria-label="Move stage">${[...stages,'Won','Lost'].map(s=>`<option ${s===d.stage?'selected':''}>${s}</option>`).join('')}</select></div><div class="prob"><i style="width:${d.probability}%"></i></div><div class="deal-meta" style="margin-top:7px"><span class="deal-owner">${d.probability}% probability</span><button class="link" data-deal-detail="${d.id}">Details</button></div></div>`).join(''):`<div class="empty">No opportunities</div>`}</div>`}).join('')}</div><div class="forecast-callout">Stage 0 submissions have no opportunity value and never enter weighted forecast totals. Qualifying a lead creates a linked opportunity in Start; rejected, duplicate and nurture records remain attached to account history.</div>`}
function projects(){const ps=state.projects.filter(p=>!searchTerm||`${p.name} ${account(p.accountId).name} ${p.group}`.toLowerCase().includes(searchTerm.toLowerCase()));const action=`<button class="btn primary" data-modal="project">${svg('plus')} New project</button>`;return pageHead('Projects','Agreements are entered once. Delivery plans, invoice actuals, and vendor costs stay distinct.',action)+(backend.connected?`<div class="notice"><span>Imported projects need review. Projects with missing required fields are in Reconciliation.</span><button class="link" data-nav="Reconciliation">Review queue</button></div>`:'')+`<div class="toolbar"><div class="search">${svg('search')}<input id="search" placeholder="Search projects or accounts" value="${esc(searchTerm)}"></div><div class="filters"><span class="pill">${ps.length} projects</span><span class="pill">${money(ps.reduce((s,p)=>s+Number(p.contractValue),0))} source contract value</span><select class="select" id="group-filter"><option value="">All groups</option>${['Strategia','Transformacia','Taktika'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="card"><div class="table-wrap">${projectTable(ps)}</div></div><div class="forecast-callout">A proportional monthly plan is the default; project revenue can be manually weighted by month. A signed project is not treated as invoiced revenue.</div>`}
function accounts(){const list=state.accounts.filter(a=>!searchTerm||`${a.name} ${a.industry} ${a.contact}`.toLowerCase().includes(searchTerm.toLowerCase()));const sizes=['Unknown','1–10','11–50','51–200','201–500','500+'];return pageHead('Accounts','Companies and people linked across leads, opportunities, projects, and suppliers.',`<button class="btn primary" data-modal="account">${svg('plus')} Add account</button>`)+`<div class="toolbar"><div class="search">${svg('search')}<input id="search" placeholder="Find a company or contact" value="${esc(searchTerm)}"></div><div class="filters"><span class="pill">${list.length} accounts</span><span class="pill">Client · Lead · Vendor</span></div></div><div class="card"><div class="table-wrap"><table class="table editable-table"><thead><tr><th>Account</th><th>Type</th><th>Industry</th><th>Company size</th><th>Primary contact</th><th>Email</th></tr></thead><tbody>${list.map(a=>`<tr><td><div class="table-name"><div class="mini-mark">${esc((a.name||'?')[0])}</div><input class="cell-editor cell-name" aria-label="Account name" data-edit-account="${esc(a.id)}" data-field="name" value="${esc(a.name)}"></div></td><td><select class="cell-editor" aria-label="Account type" data-edit-account="${esc(a.id)}" data-field="kind">${['Lead','Client','Vendor','Partner'].map(k=>`<option ${k===a.kind?'selected':''}>${k}</option>`).join('')}</select></td><td><input class="cell-editor" aria-label="Industry" data-edit-account="${esc(a.id)}" data-field="industry" value="${esc(a.industry||'')}" placeholder="Add industry"></td><td><select class="cell-editor" aria-label="Company size" data-edit-account="${esc(a.id)}" data-field="size">${[...new Set([...sizes,a.size||'Unknown'])].map(s=>`<option ${s===(a.size||'Unknown')?'selected':''}>${esc(s)}</option>`).join('')}</select></td><td><input class="cell-editor" aria-label="Primary contact" data-edit-account="${esc(a.id)}" data-field="contact" value="${esc(a.contact||'')}" placeholder="Add contact"></td><td><input class="cell-editor" aria-label="Contact email" type="email" data-edit-account="${esc(a.id)}" data-field="email" value="${esc(a.email||'')}" placeholder="Add email"></td></tr>`).join('')}</tbody></table></div></div>`}
function reports(){const s=getMonthSeries(),arr=state.projects.map(p=>({p,actual:state.costs.filter(c=>c.projectId===p.id).reduce((v,c)=>v+Number(c.actual),0),plan:state.costs.filter(c=>c.projectId===p.id).reduce((v,c)=>v+Number(c.planned),0)}));const totalCost=arr.reduce((v,x)=>v+x.plan,0),actualCost=arr.reduce((v,x)=>v+x.actual,0),activeRev=state.projects.filter(p=>p.status==='In delivery').reduce((v,p)=>v+Number(p.contractValue),0);return pageHead('Reports','A working management view. Drill into records or export the underlying data.',`<button class="btn" data-action="export">Export CSV</button><button class="btn primary" data-modal="question">Ask a question</button>`)+(backend.connected?`<div class="notice"><span>Reports cover populated projects only. Some source projects still need mapping. Pipeline import and accounting actuals are pending.</span><button class="link" data-nav="Reconciliation">Source reconciliation</button></div>`:'')+`<div class="report-grid">${reportTile('Contract value',money(contracted()),`${state.projects.length} current projects`)}${reportTile('Weighted pipeline',money(expectedPipeline()),`${state.deals.filter(d=>!['Won','Lost'].includes(d.stage)).length} open opportunities`)}${reportTile('Revenue plan · current month',money(s.find(x=>x.key===monthKey(new Date()))?.plan||0),'Delivery allocation')}${reportTile('Invoiced revenue · year to date',backend.connected&&!state.invoices.length?'Pending':money(state.invoices.filter(i=>i.issued?.startsWith(String(new Date().getFullYear()))).reduce((a,x)=>a+Number(x.amount),0)),backend.connected?'SuperFaktura reconciliation pending':'Illustrative demo invoices')}${reportTile('Planned external costs',money(totalCost),state.costs.some(c=>c.actualPending)?'Actual verification pending':`${money(actualCost)} recorded as actual`)}${reportTile('Current delivery revenue',money(activeRev),'Signed project value in delivery')}</div><div class="card" style="margin-top:15px"><div class="card-head"><div><div class="card-title">Monthly financial plan</div><div class="card-sub">Planned delivery revenue compared with invoiced revenue</div></div><span class="pill">EUR · next 4 months</span></div><div class="card-body">${chart()}</div></div><div class="card" style="margin-top:15px"><div class="card-head"><div><div class="card-title">Project margin outlook</div><div class="card-sub">Contract value less planned external costs; excludes internal costs</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Contract value</th><th>Planned vendor costs</th><th>Planned contribution</th><th>Margin</th></tr></thead><tbody>${state.projects.map(p=>{const c=state.costs.filter(x=>x.projectId===p.id).reduce((s,x)=>s+Number(x.planned),0),m=Number(p.contractValue)-c;return`<tr><td><strong>${esc(p.name)}</strong><span class="secondary">${account(p.accountId).name}</span></td><td class="money">${money(p.contractValue)}</td><td>${money(c)}</td><td class="money">${p.dataQuality&&p.dataQuality!=='Verified'?'Pending':money(m)}</td><td>${p.dataQuality&&p.dataQuality!=='Verified'?'Pending':`${p.contractValue?Math.round(m/p.contractValue*100):0}%`}</td></tr>`}).join('')}</tbody></table></div></div><p class="card-sub" style="margin:14px 2px">Numbers are separate views: signed contract value, planned delivery revenue, invoiced amounts, and planned/actual vendor costs. This first pass does not reconcile SuperFaktura automatically.</p>`}
function reportTile(label,value,sub){return`<div class="report-tile"><small>${label}</small><strong>${value}</strong><span>${sub}</span></div>`}
function settings(){return pageHead('Settings','Connect the shared Supabase workspace when its project and users are ready.')+`<div class="grid-2"><div class="card"><div class="card-head"><div><div class="card-title">Supabase connection</div><div class="card-sub">Use your project URL, publishable/anon key, and an authenticated user.</div></div><span class="status dot ${backend.connected?'green':'orange'}">${backend.connected?'Connected':'Not connected'}</span></div><div class="modal-body"><form id="settings-form" class="form-grid"><div class="field full"><label>Project URL</label><input name="url" type="url" placeholder="https://your-project.supabase.co" value="${esc(backend.url)}" required></div><div class="field full"><label>Publishable key (or anon key)</label><input name="key" autocomplete="off" placeholder="sb_publishable_…" value="${esc(backend.key)}" required></div><div class="field"><label>Team member email</label><input name="email" type="email" value="${esc(backend.email)}" required></div><div class="field"><label>Password</label><input name="password" type="password" placeholder="Supabase Auth password" required></div><div class="field full"><button class="btn primary" type="submit">${backend.connected?'Reconnect and refresh':'Connect workspace'}</button></div></form><div class="settings-note" style="margin-top:14px">The key is a client-side publishable key. Access depends on Supabase Auth and row-level policies; never enter a service-role key. Connection details are stored in this browser only. First-time setup: <a href="setup.sql" download="bizbase-setup.sql">download the setup SQL</a>. To add Pipeline stage 0 to an existing database, run the <a href="pipeline-leads-migration.sql" download="bizbase-pipeline-leads-migration.sql">lead workflow migration</a> in Supabase SQL Editor.</div>${backend.connected?`<div style="margin-top:12px"><button class="btn small" data-action="disconnect">Disconnect Supabase</button></div>`:''}</div></div><div class="card"><div class="card-head"><div><div class="card-title">How records flow</div><div class="card-sub">MVP operating model</div></div></div><div class="card-body"><div class="pipeline-list"><div><b>1 · Intake</b><div class="card-sub">Lead capture, account/contact history, manual qualification, source and review flags.</div></div><div><b>2 · Opportunity</b><div class="card-sub">Five pipeline stages, owner, next activity, expected close, amount and probability.</div></div><div><b>3 · Signed agreement</b><div class="card-sub">One agreement can contain several services and create several projects.</div></div><div><b>4 · Delivery plan</b><div class="card-sub">A monthly schedule from contract terms, with manual overrides and version history.</div></div><div><b>5 · Actuals</b><div class="card-sub">Invoices, payments, vendor commitments and costs stay separate and link to projects.</div></div></div></div></div></div><div class="card" style="margin-top:15px"><div class="card-head"><div><div class="card-title">Demo data controls</div><div class="card-sub">Sample data is fictional and remains in local browser storage.</div></div><button class="btn small" data-action="reset-demo">Reset demo data</button></div></div>`}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){state.leads??=[];let content=view==='Overview'?overview():view==='Pipeline'?pipeline():view==='Projects'?projects():view==='Accounts'?accounts():view==='Duplicate review'?duplicates.view():view==='Reports'?reports():view==='Reconciliation'?reconciliation.view():view==='Source records'?migration.view():settings();app.innerHTML=shell(content);bind();migration.bind(app);reconciliation.bind(app);duplicates.bind(app);leadWorkflow.bind(app)}
function modal(title,subtitle,body,buttons){const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="x-btn" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${buttons}</div></div>`;b.addEventListener('click',e=>{if(e.target===b||e.target.closest('[data-close]'))b.remove()});document.body.append(b);return b}
function selectAccounts(){return state.accounts.filter(a=>['Client','Partner'].includes(a.kind)||a.qualificationStatus==='Qualified'||a.qualification_status==='Qualified').map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}
async function createRawLead(f){
  state.leads??=[];state.contacts??=[];
  const email=String(f.email||'').trim().toLowerCase(),company=String(f.company||'').trim(),contactName=String(f.contact||'').trim();
  const priorContact=email?state.contacts.find(c=>String(c.email||'').trim().toLowerCase()===email):null;
  const priorAccount=priorContact?state.accounts.find(a=>a.id===priorContact.accountId):email?state.accounts.find(a=>String(a.email||'').trim().toLowerCase()===email):null;
  const companyMatches=company?state.accounts.filter(a=>a.name.trim().toLowerCase()===company.toLowerCase()):[];
  const a=priorAccount||(companyMatches.length===1?companyMatches[0]:null)||{id:uid(),name:company||contactName||email||'Unknown prospect',kind:'Lead',qualificationStatus:'Unreviewed',contact:'',email:''};
  if(!state.accounts.some(x=>x.id===a.id))state.accounts.unshift(a);
  let c=priorContact||(priorAccount?state.contacts.find(x=>x.accountId===priorAccount.id&&x.isPrimary):null);
  if(!c&&email){const parts=contactName.split(/\s+/).filter(Boolean);c={id:uid(),accountId:a.id,firstName:parts[0]||'',lastName:parts.slice(1).join(' '),email,phone:String(f.phone||'').trim(),isPrimary:!state.contacts.some(x=>x.accountId===a.id&&x.isPrimary)};state.contacts.unshift(c);if(c.isPrimary){a.contact=contactName;a.email=email;a.contactId=c.id}}
  const lead={id:uid(),accountId:a.id,contactId:c?.id||null,name:company||contactName||email||a.name,contactName,email,source:f.source||'Manual',sourceForm:String(f.sourceForm||'').trim(),submittedAt:new Date().toISOString(),reviewStatus:'Needs review',journeyStatus:'New lead',promotedOpportunityId:null,historyScanStatus:'Not run',finstatStatus:'Not checked',rawSubmission:{company_name:company,contact_name:contactName,email,phone:String(f.phone||'').trim(),source:f.source||'Manual',source_form:String(f.sourceForm||'').trim(),notes:String(f.notes||''),possible_duplicate_account_ids:companyMatches.length>1?companyMatches.map(x=>x.id):[]}};
  state.leads.unshift(lead);save();toast(priorContact?'Lead captured and linked to the existing contact history':'Raw lead added to Pipeline stage 0');
}
function reviewLead(id){
  const l=state.leads.find(x=>x.id===id);if(!l)return;const a=account(l.accountId),raw=l.rawSubmission||{};
  const historyDeals=state.deals.filter(d=>d.accountId===a.id),historyProjects=state.projects.filter(p=>p.accountId===a.id);
  const history=state.contacts.find(c=>c.id===l.contactId);
  const historySummary=[history?`Contact on file: ${[history.firstName,history.lastName].filter(Boolean).join(' ')}${history.email?` · ${history.email}`:''}`:'No matching saved contact',historyDeals.length?`Existing opportunities: ${historyDeals.map(d=>`${d.name} (${d.stage})`).join('; ')}`:'No opportunity history',historyProjects.length?`Previous/current projects: ${historyProjects.map(p=>p.name).join('; ')}`:'No project history'].join('\n');
  const body=`<div class="lead-review-summary"><strong>${esc(l.name||a.name)}</strong><span>${esc(a.name)} · ${esc(l.contactName||'Contact not named')} · ${esc(l.email||'No email')}</span><span>${esc(l.sourceForm||l.source||'Manual')} · submitted ${esc(new Date(l.submittedAt||Date.now()).toLocaleDateString('en-GB'))}</span><p>${esc(raw.notes||'No enquiry notes supplied.')}</p></div><form id="lead-review-form" class="form-grid"><div class="field"><label>Company size fit</label><select name="companySizeFit"><option>Unknown</option><option>Good fit</option><option>Outside target</option></select></div><div class="field"><label>FinStat check</label><select name="finstatStatus"><option>Not checked</option><option>Checked</option><option>Unavailable</option><option>Mismatch</option></select></div><div class="field"><label>Contact history scan</label><select name="historyScanStatus"><option>Not run</option><option>Clear</option><option>Possible match</option><option>Error</option></select></div><div class="field full"><label>Business fit</label><textarea name="businessFit" placeholder="Industry, business model, company fit"></textarea></div><div class="field full"><label>Contact history / relevant context</label><textarea name="relevantHistory" placeholder="Prior relationship, previous work, or known context">${esc(historySummary)}</textarea></div><div class="field full"><label>FinStat summary</label><input name="finstatSummary" placeholder="Optional finding or reason it could not be checked"></div><div class="field"><label>Decision</label><select name="decision"><option>Qualified</option><option>Needs more information</option><option>Nurture</option><option>Disqualified</option><option>Duplicate</option></select></div><div class="field"><label>Owner</label><input name="owner" value="${esc(a.owner||'')}" placeholder="Assign an owner"></div><div class="field full"><label>Opportunity name if qualified</label><input name="opportunityName" value="${esc(l.name||a.name)}"></div><div class="field full"><label>Review notes</label><textarea name="notes" placeholder="Reason for decision or next step"></textarea></div></form>`;
  const m=modal('Review new lead',`${a.name} · ${l.sourceForm||l.source||'Webform'}`,body,`<button class="btn" data-close>Cancel</button><button class="btn primary" type="submit" form="lead-review-form">Save review</button>`);
  m.querySelector('#lead-review-form').addEventListener('submit',async e=>{e.preventDefault();const button=m.querySelector('[type=submit]');button.disabled=true;const f=Object.fromEntries(new FormData(e.currentTarget));try{
    if(backend.connected){await supa('rpc/review_intake_lead',{method:'POST',body:JSON.stringify({p_intake_lead_id:l.id,p_decision:f.decision,p_company_size_fit:f.companySizeFit,p_business_fit:f.businessFit||null,p_relevant_history:f.relevantHistory||null,p_finstat_summary:f.finstatSummary||null,p_finstat_status:f.finstatStatus,p_history_scan_status:f.historyScanStatus,p_notes:f.notes||null,p_owner:f.owner||null,p_opportunity_name:f.opportunityName||l.name})});await reloadWorkspace();}
    else{l.reviewStatus=f.decision==='Duplicate'?'Duplicate':'Reviewed';l.journeyStatus=f.decision==='Needs more information'?'In review':f.decision;l.finstatStatus=f.finstatStatus;l.historyScanStatus=f.historyScanStatus;l.qualification={...f};if(f.decision!=='Duplicate')a.qualificationStatus=f.decision==='Needs more information'?'In review':f.decision;if(f.decision==='Qualified'){const d={id:uid(),name:f.opportunityName||l.name||a.name,accountId:a.id,stage:'Start',value:0,probability:35,owner:f.owner||'',nextActivity:'',intakeLeadId:l.id,createdAt:iso(new Date())};state.deals.unshift(d);l.promotedOpportunityId=d.id;}save();}
    m.remove();render();toast(f.decision==='Qualified'?'Qualified lead moved to Start · value remains zero until estimated':'Lead review saved');
  }catch(err){button.disabled=false;toast(`Review was not saved: ${err.message}`)}});
}
function modalForm(kind){let title,sub,fields,submit='Save';if(kind==='lead'){title='Add a raw lead';sub='Capture the original enquiry first. It stays in Pipeline stage 0 until someone reviews it.';fields=`<div class="field"><label>Company</label><input name="company" placeholder="Company name (if known)"></div><div class="field"><label>Contact name</label><input name="contact" placeholder="Contact name"></div><div class="field"><label>Email</label><input name="email" type="email" placeholder="name@company.com"></div><div class="field"><label>Phone</label><input name="phone" type="tel" placeholder="+421…"></div><div class="field"><label>Source</label><select name="source"><option>Website</option><option>Webinar</option><option>Referral</option><option>LinkedIn</option><option>Manual</option></select></div><div class="field"><label>Form name</label><input name="sourceForm" placeholder="Contact form, audit form…"></div><div class="field full"><label>Original enquiry / notes</label><textarea name="notes" placeholder="Keep the submitted request as received"></textarea></div>`}else if(kind==='deal'){title='New opportunity';sub='Add a qualified opportunity to the five-stage sales pipeline.';fields=`<div class="field full"><label>Opportunity name</label><input name="name" required placeholder="e.g. Website and content programme"></div><div class="field"><label>Account</label><select name="accountId">${selectAccounts()}</select></div><div class="field"><label>Stage</label><select name="stage">${stages.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Potential value (EUR)</label><input name="value" type="number" min="0" step="100" required></div><div class="field"><label>Expected close</label><input name="closeDate" type="date" value="${dateOffset(30)}"></div><div class="field"><label>Owner</label><input name="owner" value="Alex"></div>`}else if(kind==='account'){title='Add account';sub='Companies can become clients, leads, or vendors over time.';fields=`<div class="field"><label>Company name</label><input name="name" required></div><div class="field"><label>Type</label><select name="kind"><option>Lead</option><option>Client</option><option>Vendor</option></select></div><div class="field"><label>Industry</label><input name="industry"></div><div class="field"><label>Company size</label><select name="size"><option>Unknown</option><option>1–10</option><option>11–50</option><option>51–200</option><option>201–500</option><option>500+</option></select></div><div class="field"><label>Primary contact</label><input name="contact"></div><div class="field"><label>Contact email</label><input name="email" type="email"></div>`}else if(kind==='project'){title='Create a project';sub='Enter signed work once, then set the revenue schedule and costs.';fields=`<div class="field full"><label>Project name</label><input name="name" required placeholder="Project name"></div><div class="field full"><label>Agreement</label><select name="agreementId"><option value="">Create a new agreement</option>${(state.agreements||[]).map(a=>`<option value="${a.id}">${esc(a.name)} · ${money(a.totalValue)} total</option>`).join('')}</select></div><div class="field"><label>Account</label><select name="accountId">${selectAccounts()}</select></div><div class="field"><label>Project group</label><select name="group"><option>Strategia</option><option>Transformacia</option><option>Taktika</option></select></div><div class="field"><label>Contract value (EUR)</label><input name="value" type="number" min="0" step="100" required></div><div class="field"><label>Delivery pattern</label><select name="pattern"><option value="proportional">Proportional monthly</option><option value="manual">Enter monthly amounts</option></select></div><div class="field full" data-manual-schedule style="display:none"><label>Monthly amounts in EUR, comma separated (must equal contract value)</label><input name="manualSchedule" placeholder="e.g. 2000, 3000, 1000"></div><div class="field"><label>Start date</label><input name="startDate" type="date" value="${iso(new Date())}" required></div><div class="field"><label>End date</label><input name="endDate" type="date" value="${dateOffset(180)}" required></div><div class="field"><label>Service(s) included</label><input name="services" placeholder="e.g. New website, LinkedIn management"></div><div class="field"><label>Owner</label><input name="owner" value="Alex"></div>`}else if(kind==='cost'){const p=project(selectedProject);title='Add vendor cost';sub=`Link a supplier cost to ${p?.name||'this project'}.`;fields=`<div class="field"><label>Vendor</label><input name="vendor" required></div><div class="field"><label>Description</label><input name="description" required></div><div class="field"><label>Planned cost (EUR)</label><input name="planned" type="number" min="0" step="10" required></div><div class="field"><label>Actual cost (EUR)</label><input name="actual" type="number" min="0" step="10" value="0"></div><div class="field"><label>Status</label><select name="status"><option>Planned</option><option>Ordered</option><option>In progress</option><option>Invoiced</option><option>Paid</option></select></div>`}else return;const m=modal(title,sub,`<form id="modal-form" class="form-grid">${fields}</form>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" type="submit" form="modal-form">${submit}</button>`);m.querySelector('[name=pattern]')?.addEventListener('change',e=>{const field=m.querySelector('[data-manual-schedule]');if(field)field.style.display=e.target.value==='manual'?'grid':'none'});m.querySelector('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(kind==='lead'){await createRawLead(f);m.remove();render();return}if(kind==='account'){state.accounts.unshift({id:uid(),...f});toast('Account added')}if(kind==='deal'){const d={id:uid(),name:f.name,accountId:f.accountId,stage:f.stage,value:+f.value,probability:{'Start':35,'Meeting planned':37,'Meeting has happened':38,'Quote in process':50,'Quote sent':52}[f.stage],owner:f.owner,nextActivity:dateOffset(5),expectedClose:f.closeDate};state.deals.unshift(d);toast('Opportunity added to pipeline')}if(kind==='project'){const p={id:uid(),name:f.name,accountId:f.accountId,group:f.group,status:'Scheduled',contractValue:+f.value,startDate:f.startDate,endDate:f.endDate,owner:f.owner,services:String(f.services||'').split(',').map(s=>s.trim()).filter(Boolean).map(name=>({name,value:0}))};let plans;try{plans=scheduleRows(p.id,+f.value,f.startDate,f.endDate,f.pattern,f.manualSchedule||'')}catch(err){toast(err.message);return}let agreement=state.agreements.find(a=>a.id===f.agreementId);if(agreement){if(agreement.accountId!==f.accountId){toast('Choose an agreement for the selected account.');return}const used=state.projects.filter(x=>x.agreementId===agreement.id).reduce((sum,x)=>sum+Number(x.contractValue),0);if(used+Number(f.value)>Number(agreement.totalValue)+.01){toast(`This agreement has ${money(agreement.totalValue-used)} unallocated.`);return}}else{agreement={id:uid(),accountId:f.accountId,name:f.name,totalValue:+f.value,status:'Signed',startDate:f.startDate,endDate:f.endDate};state.agreements.unshift(agreement)}p.agreementId=agreement.id;state.projects.unshift(p);state.plans.unshift(...plans);toast('Project and revenue plan created')}if(kind==='cost'){state.costs.unshift({id:uid(),projectId:selectedProject,vendor:f.vendor,description:f.description,planned:+f.planned,actual:+f.actual,status:f.status,date:iso(new Date())});toast('Vendor cost linked to project')}save();m.remove();render()})}
function projectDetail(id){selectedProject=id;const p=project(id);if(!p)return;const costs=state.costs.filter(x=>x.projectId===id),invoices=state.invoices.filter(x=>x.projectId===id),plan=state.plans.find(x=>x.projectId===id),plannedCosts=costs.reduce((s,c)=>s+Number(c.planned),0),actualCosts=costs.reduce((s,c)=>s+Number(c.actual),0);const body=`<div class="project-summary"><div class="project-avatar">${p.group[0]}</div><div><b>${esc(p.name)}</b><div class="card-sub">${esc(account(p.accountId).name)} · ${p.group} · ${p.status}</div></div></div><div class="detail-grid" style="margin-top:16px"><div class="detail-box"><label>Contract value</label><strong>${money(p.contractValue)}</strong></div><div class="detail-box"><label>Expected contribution</label><strong>${p.dataQuality&&p.dataQuality!=='Verified'?'Needs reconciliation':money(p.contractValue-plannedCosts)}</strong></div><div class="detail-box"><label>Delivery window</label><strong style="font-size:13px">${p.startDate||'Not set'} → ${p.endDate||'Not set'}</strong></div><div class="detail-box"><label>Revenue plan</label><strong style="font-size:13px">${!plan?'Not mapped':plan.method==='proportional'?'Proportional monthly':'Source monthly schedule'}</strong></div></div><div style="margin-top:18px"><div class="split"><b>Services</b><span class="card-sub">${p.services?.length||0} included</span></div><div class="table-wrap"><table class="table"><tbody>${(p.services||[]).map(s=>`<tr><td>${esc(s.name)}</td><td class="money">${s.value?money(s.value):'Part of agreement'}</td></tr>`).join('')||'<tr><td>Services not itemised yet</td></tr>'}</tbody></table></div></div><div style="margin-top:16px"><div class="split"><b>Vendor costs</b><button class="btn small" data-modal="cost">+ Add cost</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Vendor / description</th><th>Status</th><th>Planned</th><th>Actual</th></tr></thead><tbody>${costs.map(c=>`<tr><td><strong>${esc(c.vendor)}</strong><span class="secondary">${esc(c.description)}</span></td><td>${esc(c.status)}</td><td>${money(c.planned)}</td><td>${c.actualPending?'Pending verification':money(c.actual)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No vendor costs recorded.</td></tr>'}</tbody></table></div></div><div style="margin-top:16px"><div class="split"><b>Invoice actuals</b><span class="card-sub">A single invoice can be allocated across projects.</span></div><table class="table"><tbody>${invoices.map(i=>`<tr><td>${esc(i.number)}</td><td>${i.issued}</td><td><span class="status dot green">${i.status}</span></td><td class="money">${money(i.amount)}</td></tr>`).join('')||'<tr><td class="empty">No reconciled invoices recorded.</td></tr>'}</tbody></table></div><div class="forecast-callout">Financial views keep contract value, planned delivery revenue, invoice actuals and supplier costs distinct. Actual recognized revenue and cash collection need accounting and SuperFaktura reconciliation rules before production reporting.</div>`;const m=modal(p.name,`${account(p.accountId).name} · ${p.owner||'Unassigned'}`,body,`<button class="btn" data-close>Close</button><button class="btn primary" data-modal="cost">+ Vendor cost</button>`);m.querySelectorAll('[data-modal="cost"]').forEach(b=>b.addEventListener('click',()=>{m.remove();modalForm('cost')}))}
function detailDeal(id){const d=state.deals.find(x=>x.id===id);if(!d)return;const body=`<div class="detail-grid"><div class="detail-box"><label>Account</label><strong style="font-size:14px">${esc(account(d.accountId).name)}</strong></div><div class="detail-box"><label>Potential</label><strong>${money(d.value)}</strong></div><div class="detail-box"><label>Stage / probability</label><strong style="font-size:14px">${d.stage} · ${d.probability}%</strong></div><div class="detail-box"><label>Expected weighted value</label><strong>${money(d.value*d.probability/100)}</strong></div></div><div class="forecast-callout">Marking the opportunity Won will ask for the agreed delivery plan and create project records. Won opportunities leave the open weighted pipeline.</div>`;const m=modal(d.name,'Opportunity details',body,`<button class="btn" data-close>Close</button><button class="btn primary" data-won>Mark won & create project</button>`);m.querySelector('[data-won]').onclick=()=>{m.remove();closeDealAsWon(d)}}
function closeDealAsWon(d){const body=`<form id="won-form" class="form-grid"><div class="field full"><label>Project name</label><input name="name" required value="${esc(d.name)}"></div><div class="field"><label>Project group</label><select name="group"><option>Strategia</option><option>Transformacia</option><option>Taktika</option></select></div><div class="field"><label>Agreed value (EUR)</label><input name="value" type="number" value="${d.value}" required></div><div class="field"><label>Delivery starts</label><input name="startDate" type="date" value="${iso(new Date())}" required></div><div class="field"><label>Delivery ends</label><input name="endDate" type="date" value="${dateOffset(180)}" required></div><div class="field"><label>Schedule</label><select name="pattern"><option value="proportional">Proportional monthly</option><option value="manual">Enter monthly amounts</option></select></div><div class="field full" data-manual-schedule style="display:none"><label>Monthly amounts in EUR, comma separated (must equal agreement value)</label><input name="manualSchedule" placeholder="e.g. 2000, 3000, 1000"></div><div class="field"><label>Services included</label><input name="services" placeholder="Comma separated service names"></div></form>`;const m=modal('Create delivery project',`Convert ${d.name} into a signed project.`,body,`<button class="btn" data-close>Cancel</button><button class="btn primary" type="submit" form="won-form">Create project</button>`);m.querySelector('[name=pattern]')?.addEventListener('change',e=>{m.querySelector('[data-manual-schedule]').style.display=e.target.value==='manual'?'grid':'none'});m.querySelector('#won-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const p={id:uid(),name:f.name,accountId:d.accountId,group:f.group,status:'Scheduled',contractValue:+f.value,startDate:f.startDate,endDate:f.endDate,owner:d.owner,services:String(f.services).split(',').map(x=>x.trim()).filter(Boolean).map(name=>({name,value:0}))};let plans;try{plans=scheduleRows(p.id,+f.value,f.startDate,f.endDate,f.pattern,f.manualSchedule||'')}catch(err){toast(err.message);return}const agreement={id:uid(),accountId:d.accountId,name:f.name,totalValue:+f.value,status:'Signed',startDate:f.startDate,endDate:f.endDate,opportunityId:d.id};state.agreements.unshift(agreement);p.agreementId=agreement.id;state.projects.unshift(p);state.plans.unshift(...plans);d.stage='Won';save();m.remove();navigate('Projects');toast('Won opportunity converted to an agreement and project')}}

async function supa(path,opts={}){return supabaseSession.request(path,opts)}
async function writeRow(table,row,method='POST',filter=''){if(!backend.connected)return;await supa(`${table}${filter?`?${filter}`:''}`,{method,body:JSON.stringify(row),headers:{Prefer:'resolution=merge-duplicates,return=representation'}})}
async function syncState(){if(!backend.connected)return;for(const a of state.accounts){if(a.source_external_id)continue;await writeRow('accounts',{id:a.id,name:a.name,kind:a.kind||'Lead',industry:a.industry||null,company_size:a.size||null,qualification_status:a.qualificationStatus||'Unreviewed',qualification_notes:a.qualificationNotes||null,data_quality_status:a.data_quality_status||'Needs review'},'POST','on_conflict=id');if(a.contact||a.email){a.contactId||=uid();const parts=String(a.contact||'').trim().split(/\s+/);await writeRow('contacts',{id:a.contactId,account_id:a.id,first_name:parts[0]||null,last_name:parts.slice(1).join(' ')||null,email:a.email||null,is_primary:true},'POST','on_conflict=id')}}for(const c of state.contacts||[]){await writeRow('contacts',{id:c.id,account_id:c.accountId,first_name:c.firstName||null,last_name:c.lastName||null,email:c.email||null,phone:c.phone||null,role_title:c.roleTitle||null,is_primary:!!c.isPrimary},'POST','on_conflict=id')}for(const d of state.deals){await writeRow('opportunities',{id:d.id,account_id:d.accountId,name:d.name,stage:d.stage,amount:d.value,probability:d.probability,expected_close:d.expectedClose||null,next_activity:d.nextActivity||null,owner:d.owner||null,intake_lead_id:d.intakeLeadId||null},'POST','on_conflict=id')}for(const a of state.agreements||[]){await writeRow('agreements',{id:a.id,opportunity_id:a.opportunityId||null,account_id:a.accountId,name:a.name,status:a.status||'Signed',currency:'EUR',total_value:a.totalValue,signed_on:a.signedOn||null,delivery_start:a.startDate||null,delivery_end:a.endDate||null},'POST','on_conflict=id')}for(const p of state.projects){if(p.sourceExternalId)continue;await writeRow('projects',{id:p.id,agreement_id:p.agreementId||null,account_id:p.accountId,name:p.name,project_group:p.group,status:p.status,contract_value:p.contractValue,start_date:p.startDate||null,end_date:p.endDate||null,owner:p.owner||null,data_quality_status:p.dataQuality||'Needs review'},'POST','on_conflict=id');for(const s of p.services||[]){if(!s.id)s.id=uid();await writeRow('project_services',{id:s.id,project_id:p.id,service_name:s.name,amount:s.value||0},'POST','on_conflict=id')}const rows=state.plans.filter(x=>x.projectId===p.id);for(const q of rows){if(q.month){await writeRow('revenue_plans',{project_id:p.id,plan_month:`${q.month.slice(0,7)}-01`,planned_amount:q.value,allocation_method:q.method==='proportional'?'Proportional':'Manual',is_manual_override:q.method!=='proportional'},'POST','on_conflict=project_id,plan_month')}else{const from=new Date(`${q.startDate.slice(0,7)}-01T12:00:00`),to=new Date(`${q.endDate.slice(0,7)}-01T12:00:00`),n=(to.getFullYear()-from.getFullYear())*12+to.getMonth()-from.getMonth()+1;for(let j=0;j<n;j++){const dt=new Date(from);dt.setMonth(dt.getMonth()+j);const m=dt.toISOString().slice(0,7);await writeRow('revenue_plans',{project_id:p.id,plan_month:`${m}-01`,planned_amount:q.method==='proportional'?Math.round((q.value/n)*100)/100:q.value,allocation_method:q.method==='proportional'?'Proportional':'Manual',is_manual_override:q.method!=='proportional'},'POST','on_conflict=project_id,plan_month')}}}}for(const c of state.costs){if(c.sourceExternalId)continue;await writeRow('vendor_costs',{id:c.id,project_id:c.projectId,vendor_name:c.vendor,description:c.description,planned_amount:c.planned,actual_amount:c.actual,status:c.status,expected_date:c.date||null},'POST','on_conflict=id')}for(const l of state.leads||[]){await writeRow('intake_leads',{id:l.id,account_id:l.accountId,contact_id:l.contactId||null,source:l.source||'Manual',source_form:l.sourceForm||null,source_external_id:l.sourceExternalId||null,submitted_at:l.submittedAt||new Date().toISOString(),review_status:l.reviewStatus||'Needs review',journey_status:l.journeyStatus||'New lead',promoted_opportunity_id:l.promotedOpportunityId||null,history_scan_status:l.historyScanStatus||'Not run',finstat_status:l.finstatStatus||'Not checked',raw_submission:l.rawSubmission||{notes:l.notes||''}},'POST','on_conflict=id')}}
async function connect(form){const f=Object.fromEntries(new FormData(form));const url=f.url.replace(/\/$/,'');const r=await fetch(`${url}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:f.key,'Content-Type':'application/json'},body:JSON.stringify({email:f.email,password:f.password})});if(!r.ok)throw new Error('Sign-in failed. Check the project URL, key, email and password.');const session=await r.json();backend={url,key:f.key,email:f.email,password:'',token:session.access_token,refreshToken:session.refresh_token,expiresAt:Math.floor(Date.now()/1000)+Number(session.expires_in||3600),sessionExpired:false,connected:true};localStorage.setItem('bc_backend',JSON.stringify(backend));await reloadWorkspace();toast('Supabase connected.');}
async function reloadWorkspace(){if(!backend.connected)return;const tables=['accounts','contacts','intake_leads','opportunities','projects','project_services','revenue_plans','vendor_costs','invoices','invoice_allocations','agreements'];const [as,cs,ls,ds,ps,ss,rs,vs,is,ias,ags]=await Promise.all(tables.map(t=>readAll(supa,t)));state={contacts:cs.map(c=>({id:c.id,accountId:c.account_id,firstName:c.first_name||'',lastName:c.last_name||'',email:c.email||'',phone:c.phone||'',roleTitle:c.role_title||'',isPrimary:!!c.is_primary})),leads:ls.map(l=>({id:l.id,accountId:l.account_id,contactId:l.contact_id,name:l.raw_submission?.contact_name||l.raw_submission?.company_name||'',contactName:l.raw_submission?.contact_name||'',email:l.raw_submission?.email||'',source:l.source,sourceForm:l.source_form,submittedAt:l.submitted_at,reviewStatus:l.review_status,journeyStatus:l.journey_status||'New lead',promotedOpportunityId:l.promoted_opportunity_id,sourceExternalId:l.source_external_id,rawSubmission:l.raw_submission||{}})),agreements:ags.map(a=>({id:a.id,accountId:a.account_id,name:a.name,totalValue:Number(a.total_value||0),status:a.status,startDate:a.delivery_start,endDate:a.delivery_end,opportunityId:a.opportunity_id})),accounts:as.map(a=>({...a,kind:a.kind||'Lead',size:a.company_size,qualificationStatus:a.qualification_status,contactId:cs.find(c=>c.account_id===a.id&&c.is_primary)?.id,contact:cs.filter(c=>c.account_id===a.id&&c.is_primary).map(c=>[c.first_name,c.last_name].filter(Boolean).join(' ')).join(', '),email:cs.find(c=>c.account_id===a.id&&c.is_primary)?.email||''})),deals:ds.map(d=>({id:d.id,name:d.name,accountId:d.account_id,stage:d.stage,value:Number(d.amount||0),probability:Number(d.probability||0),owner:d.owner||'',nextActivity:d.next_activity||'',expectedClose:d.expected_close,intakeLeadId:d.intake_lead_id||null})),projects:ps.map(p=>({id:p.id,name:p.name,accountId:p.account_id,agreementId:p.agreement_id,group:p.project_group,status:p.status,sourceExternalId:p.source_external_id,dataQuality:p.data_quality_status,contractValue:Number(p.contract_value||0),startDate:p.start_date||null,endDate:p.end_date||null,owner:p.owner||'',services:ss.filter(s=>s.project_id===p.id).map(s=>({id:s.id,name:s.service_name,value:Number(s.amount||0)}))})),plans:rs.map(r=>({projectId:r.project_id,value:Number(r.planned_amount||0),startDate:r.plan_month,endDate:r.plan_month,method:r.allocation_method==='Proportional'?'proportional':'manual',month:r.plan_month})),costs:vs.map(v=>({id:v.id,projectId:v.project_id,vendor:v.vendor_name,description:v.description,planned:Number(v.planned_amount||0),actual:Number(v.actual_amount||0),status:v.status,date:v.expected_date,sourceExternalId:v.source_external_id,actualPending:!!v.notes?.includes('ACTUAL_PENDING')})),invoices:ias.map(a=>{const i=is.find(x=>x.id===a.invoice_id);return i?{id:i.id,projectId:a.project_id,number:i.invoice_number||'Invoice',amount:Number(a.allocated_amount||0),issued:i.issued_on,status:i.status}:null}).filter(Boolean)};localStorage.setItem('bc_state',JSON.stringify(state));render();return {accounts:as.length,projects:ps.length,leads:ls.length}}
function exportData(){const rows=[['record_type','id','name','account','amount_eur','status','start_date','end_date']];state.projects.forEach(p=>rows.push(['project',p.id,p.name,account(p.accountId).name,p.contractValue,p.status,p.startDate,p.endDate]));state.deals.forEach(d=>rows.push(['opportunity',d.id,d.name,account(d.accountId).name,d.value,d.stage,'','']));const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='business-console-export.csv';a.click();URL.revokeObjectURL(a.href);toast('CSV export downloaded')}
function bind(){app.querySelectorAll('[data-nav]').forEach(x=>x.onclick=e=>{e.preventDefault();searchTerm='';navigate(x.dataset.nav)});app.querySelectorAll('[data-modal]').forEach(x=>x.onclick=()=>modalForm(x.dataset.modal));app.querySelector('[data-menu]')?.addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));app.querySelector('#search')?.addEventListener('input',e=>{searchTerm=e.target.value;const pos=e.target.selectionStart;render();const n=app.querySelector('#search');if(n){n.focus();n.setSelectionRange(pos,pos)}});app.querySelectorAll('[data-project]').forEach(x=>x.onclick=e=>{if(!e.target.closest('.cell-editor'))projectDetail(x.dataset.project)});app.querySelectorAll('[data-deal-detail]').forEach(x=>x.onclick=()=>detailDeal(x.dataset.dealDetail));app.querySelectorAll('.stage-change').forEach(x=>x.onchange=()=>{const d=state.deals.find(y=>y.id===x.dataset.deal);if(x.value==='Won'){closeDealAsWon(d)}else if(x.value==='Lost'){d.stage='Lost';save();render();toast('Opportunity marked lost')}else{d.stage=x.value;d.probability={'Start':35,'Meeting planned':37,'Meeting has happened':38,'Quote in process':50,'Quote sent':52}[d.stage];save();render();toast('Opportunity stage updated')}});app.querySelector('#group-filter')?.addEventListener('change',e=>{const value=e.target.value;const rows=app.querySelectorAll('[data-project]');rows.forEach(r=>r.style.display=!value||project(r.dataset.project)?.group===value?'':'none')});app.querySelectorAll('[data-action="export"]').forEach(x=>x.onclick=exportData);app.querySelector('[data-action="reset-demo"]')?.addEventListener('click',()=>{if(confirm('Reset local demo records to the fictional starting data?')){state=structuredClone(seed);save();render();toast('Demo data reset')}});app.querySelector('[data-action="disconnect"]')?.addEventListener('click',()=>{backend={url:'',key:'',email:'',password:'',token:'',connected:false};localStorage.removeItem('bc_backend');render();toast('Disconnected; browser demo data remains available')});app.querySelector('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;b.textContent='Connecting…';try{await connect(e.currentTarget)}catch(err){toast(err.message||'Could not connect');b.disabled=false;b.textContent='Connect workspace'}});app.querySelector('[data-modal="question"]')?.addEventListener('click',()=>modal('Ask your data','Ad-hoc AI reporting is planned after verified data access and definitions are in place.',`<div class="field"><label>What would you like to understand?</label><textarea placeholder="e.g. How much revenue is planned for Q1 next year, and what is the delivery margin outlook?"></textarea></div><div class="settings-note" style="margin-top:12px">AI answers are not wired to live company data in this MVP. This button captures the intended interaction; use the report cards and CSV export for now.</div>`,`<button class="btn" data-close>Close</button><button class="btn primary" data-close>Got it</button>`))}
app.addEventListener('change',async e=>{
  const el=e.target.closest('.cell-editor');if(!el)return;
  const field=el.dataset.field,value=el.type==='number'?Number(el.value):el.value;
  const entity=el.dataset.editProject?project(el.dataset.editProject):state.accounts.find(a=>a.id===el.dataset.editAccount);if(!entity)return;
  const before=entity[field];entity[field]=value;el.disabled=true;
  try{
    if(backend.connected){
      if(el.dataset.editProject){const columns={name:'name',group:'project_group',status:'status',contractValue:'contract_value',endDate:'end_date',owner:'owner'};if(!columns[field])throw Error('Unknown project field');await supa(`projects?id=eq.${entity.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({[columns[field]]:value===''?null:value})});}
      else if(field==='contact'||field==='email'){
        const row={account_id:entity.id,first_name:entity.contact||null,last_name:null,email:entity.email||null,is_primary:true};entity.contactId||=uid();await writeRow('contacts',{id:entity.contactId,...row},'POST','on_conflict=id');
      }else{const columns={name:'name',kind:'kind',industry:'industry',size:'company_size'};if(!columns[field])throw Error('Unknown account field');await supa(`accounts?id=eq.${entity.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({[columns[field]]:value==='Unknown'||value===''?null:value})});}
    }
    localStorage.setItem('bc_state',JSON.stringify(state));toast('Change saved');
  }catch(err){entity[field]=before;toast(`Change was not saved: ${err.message}`);}
  finally{render();}
});

render();
if(backend.connected)reloadWorkspace().catch(e=>toast(`Workspace refresh failed: ${e.message}`));
